import{_ as a,o as d,c as o,a3 as i}from"./chunks/framework.rPoJfhSN.js";const h=JSON.parse('{"title":"Cuentas demo","description":"","frontmatter":{},"headers":[],"relativePath":"guia/cuentas-demo.md","filePath":"guia/cuentas-demo.md","lastUpdated":null}'),t={name:"guia/cuentas-demo.md"};function r(s,e,n,l,c,p){return d(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="cuentas-demo" tabindex="-1">Cuentas demo <a class="header-anchor" href="#cuentas-demo" aria-label="Permalink to &quot;Cuentas demo&quot;">​</a></h1><p>Plazora incluye tres cuentas para recorrer los flujos principales después de una instalación local. Las mismas credenciales están definidas tanto en los seeders como en <code>database/database.sql</code>.</p><h2 id="credenciales" tabindex="-1">Credenciales <a class="header-anchor" href="#credenciales" aria-label="Permalink to &quot;Credenciales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Perfil</th><th>Acceso</th><th>Correo</th><th>Contraseña</th></tr></thead><tbody><tr><td>Administrador</td><td><code>/admin/login</code></td><td><code>admin@plazora.test</code></td><td><code>PlazoraDemo2026!</code></td></tr><tr><td>Vendedor</td><td><code>/login</code></td><td><code>vendedor@plazora.test</code></td><td><code>PlazoraDemo2026!</code></td></tr><tr><td>Cliente</td><td><code>/login</code></td><td><code>cliente@plazora.test</code></td><td><code>PlazoraDemo2026!</code></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Exclusivamente para local</p><p>Estas credenciales son públicas porque forman parte de la documentación. No deben existir en producción. Antes de publicar Plazora, cambia la contraseña del administrador y elimina, desactiva o reemplaza las cuentas demo.</p></div><h2 id="administrador" tabindex="-1">Administrador <a class="header-anchor" href="#administrador" aria-label="Permalink to &quot;Administrador&quot;">​</a></h2><p>La cuenta administrativa recibe el rol <code>Super Admin</code>. Permite revisar dashboard, catálogo, pedidos, vendedores, KYC, retiros, permisos, contenido y configuración global.</p><p>El administrador usa un guard separado; por ello debe iniciar sesión en <code>/admin/login</code>, no en el formulario público.</p><h2 id="vendedor" tabindex="-1">Vendedor <a class="header-anchor" href="#vendedor" aria-label="Permalink to &quot;Vendedor&quot;">​</a></h2><p>La cuenta del vendedor queda preparada para entrar directamente al panel:</p><ul><li>tipo de usuario <code>vendor</code>;</li><li>correo verificado;</li><li>tienda <code>Tienda Demo Plazora</code>;</li><li>KYC aprobado;</li><li>cartera creada con saldo inicial en cero.</li></ul><p>Después del login, la aplicación redirige al dashboard bajo <code>/vendor/dashboard</code>. Esta cuenta permite probar perfil de tienda, productos, pedidos, métodos de retiro y solicitudes.</p><h2 id="cliente" tabindex="-1">Cliente <a class="header-anchor" href="#cliente" aria-label="Permalink to &quot;Cliente&quot;">​</a></h2><p>La cuenta de cliente tiene tipo <code>user</code> y correo verificado. Sirve para probar perfil, direcciones, carrito, wishlist, checkout, pedidos, reseñas y descargas digitales.</p><h2 id="segun-el-metodo-de-instalacion" tabindex="-1">Según el método de instalación <a class="header-anchor" href="#segun-el-metodo-de-instalacion" aria-label="Permalink to &quot;Según el método de instalación&quot;">​</a></h2><h3 id="importacion-del-sql" tabindex="-1">Importación del SQL <a class="header-anchor" href="#importacion-del-sql" aria-label="Permalink to &quot;Importación del SQL&quot;">​</a></h3><p>Al importar <code>database/database.sql</code>, las cuentas ya están presentes con el hash de la contraseña demo. El vendedor corresponde a la tienda y KYC incluidos en el snapshot.</p><h3 id="migraciones-y-seeders" tabindex="-1">Migraciones y seeders <a class="header-anchor" href="#migraciones-y-seeders" aria-label="Permalink to &quot;Migraciones y seeders&quot;">​</a></h3><p><code>AdminSeeder</code> crea o actualiza al administrador y su rol. <code>UserSeeder</code> crea o actualiza cliente, vendedor, tienda, KYC y cartera. Los seeders usan operaciones repetibles para reducir duplicados al ejecutarlos nuevamente en un entorno local.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Este comando se muestra como referencia, pero recuerda que los seeders actuales no reconstruyen todo el catálogo del snapshot SQL. Consulta <a href="/docs/decisiones/001-sql-vs-seeders.html">SQL frente a seeders</a>.</p><h2 id="checklist-antes-de-produccion" tabindex="-1">Checklist antes de producción <a class="header-anchor" href="#checklist-antes-de-produccion" aria-label="Permalink to &quot;Checklist antes de producción&quot;">​</a></h2><ol><li>Cambia la contraseña de cualquier administrador conservado.</li><li>Elimina o desactiva <code>cliente@plazora.test</code> y <code>vendedor@plazora.test</code>.</li><li>Revisa administradores, roles y permisos existentes.</li><li>Rota claves de correo, base de datos y pasarelas.</li><li>Confirma que ninguna cuenta documentada pueda autenticarse.</li></ol>',23)])])}const m=a(t,[["render",r]]);export{h as __pageData,m as default};
